package com.vibeguard.samples.oauth; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Exchanges one-time opaque refresh values after client authentication. */ @RestController public class TokenController { private final Map<String,String> refreshes=new ConcurrentHashMap<>(); @Value("${OAUTH_CLIENT_KEY:}") private String clientKey; @Value("${OAUTH_INTERNAL_KEY:}") private String internalKey; @PostMapping("/internal/refresh-tokens") public ResponseEntity<Token> issue(@RequestHeader("X-OAuth-Internal-Key") String supplied,@Valid @RequestBody Request request){if(!internalKey.equals(supplied))return ResponseEntity.status(401).build();String refresh=UUID.randomUUID().toString();refreshes.put(refresh,request.subject());return ResponseEntity.status(201).body(new Token(UUID.randomUUID().toString(),refresh,"Bearer",3600));}@PostMapping("/oauth/token") public ResponseEntity<Token> refresh(@RequestHeader("X-OAuth-Client-Key") String supplied,@Valid @RequestBody Refresh request){if(!clientKey.equals(supplied)||!"refresh_token".equals(request.grantType()))return ResponseEntity.status(401).build();String subject=refreshes.remove(request.refreshToken());if(subject==null)return ResponseEntity.status(400).build();String next=UUID.randomUUID().toString();refreshes.put(next,subject);return ResponseEntity.ok(new Token(UUID.randomUUID().toString(),next,"Bearer",3600));}record Request(@NotBlank String subject){}record Refresh(@NotBlank String grantType,@NotBlank String refreshToken){}record Token(String accessToken,String refreshToken,String tokenType,int expiresIn){} }
